const requeueStalledProcessingJob = `-- name: RequeueStalledProcessingJob :one
WITH requeued AS (
    UPDATE foghorn.processing_jobs AS job
    SET status = 'queued', processing_node_id = NULL, updated_at = NOW(),
        error_message = $1,
        progress_last_ms = 0, progress_advanced_at = NULL,
        source_stalled_since = COALESCE(job.source_stalled_since, job.started_at, NOW()),
        next_attempt_at = LEAST(
            NOW() + (NOW() - COALESCE(job.source_stalled_since, job.started_at, NOW())),
            COALESCE(job.source_stalled_since, job.started_at, NOW()) + CAST($2 AS text)::interval)
    WHERE job.job_id = $3
      AND job.processing_node_id = $4
      AND job.status IN ('dispatched', 'processing')
      AND COALESCE(job.source_stalled_since, job.started_at, NOW()) > NOW() - CAST($2 AS text)::interval
    RETURNING artifact_hash, tenant_id
), artifact AS (
    UPDATE foghorn.artifacts AS a
    SET status = 'queued', updated_at = NOW()
    FROM requeued AS r
    WHERE a.artifact_hash = r.artifact_hash
      AND a.tenant_id = r.tenant_id
      AND a.artifact_type IN ('clip', 'vod')
      AND a.status NOT IN ('ready', 'failed', 'deleted', 'expired', 'aborted')
    RETURNING a.artifact_hash
)
SELECT COUNT(*)::int AS requeued FROM requeued
`

type RequeueStalledProcessingJobParams struct {
	ErrorMessage sql.NullString `db:"error_message" json:"error_message"`
	StallWindow  string         `db:"stall_window" json:"stall_window"`
	JobID        string         `db:"job_id" json:"job_id"`
	NodeID       sql.NullString `db:"node_id" json:"node_id"`
}

// Requeues a job whose node reported its source read stalled in storage or
// upstream. The attempt does not draw from the retry budget: it is bounded by
// how long the run of stalls has lasted, measured from the first stalled
// attempt's start, and backs off by that same elapsed time, never past the end
// of the window. Bound to the reporting node like every result.
func (q *Queries) RequeueStalledProcessingJob(ctx context.Context, arg RequeueStalledProcessingJobParams) (int32, error) {
	row := q.db.QueryRowContext(ctx, requeueStalledProcessingJob,
		arg.ErrorMessage,
		arg.StallWindow,
		arg.JobID,
		arg.NodeID,
	)
	var requeued int32
	err := row.Scan(&requeued)
	return requeued, err
}

const requeueUnreportedNodeProcessingJobs = `-- name: RequeueUnreportedNodeProcessingJobs :execrows
WITH requeued AS (
    UPDATE foghorn.processing_jobs AS job
    SET status = 'queued', processing_node_id = NULL,
        retry_count = retry_count + 1, updated_at = NOW(),
        progress_last_ms = 0, progress_advanced_at = NULL
    WHERE job.processing_node_id = $1
      AND job.status IN ('dispatched', 'processing')
      -- Assignment time, not updated_at: a running job's progress moves
      -- updated_at every second, which would exclude every active job.
      AND COALESCE(job.started_at, job.updated_at) < $2
      AND job.retry_count < $3
      AND NOT (job.job_id::text = ANY($4::text[]))
    RETURNING artifact_hash, tenant_id
)
UPDATE foghorn.artifacts AS a
SET status = 'queued', updated_at = NOW()
FROM requeued AS r
WHERE a.artifact_hash = r.artifact_hash
  AND a.tenant_id = r.tenant_id
  AND a.artifact_type IN ('clip', 'vod')
  AND a.status NOT IN ('ready', 'failed', 'deleted', 'expired', 'aborted')
`

type RequeueUnreportedNodeProcessingJobsParams struct {
	NodeID         sql.NullString `db:"node_id" json:"node_id"`
	AssignedBefore sql.NullTime   `db:"assigned_before" json:"assigned_before"`
	MaxRetries     sql.NullInt32  `db:"max_retries" json:"max_retries"`
	ReportedJobIds []string       `db:"reported_job_ids" json:"reported_job_ids"`
}

// Requeues the jobs assigned to a node before its registration that the node
// did not report as running: a restarted sidecar lost them.
func (q *Queries) RequeueUnreportedNodeProcessingJobs(ctx context.Context, arg RequeueUnreportedNodeProcessingJobsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, requeueUnreportedNodeProcessingJobs,
		arg.NodeID,
		arg.AssignedBefore,
		arg.MaxRetries,
		pq.Array(arg.ReportedJobIds),
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

